@preconcurrency import SwiftNumber
@preconcurrency import Eth
import Foundation

public enum LoopLong {
    public struct LoopInfo: Equatable, Sendable {
        public static let schema: ABI.Schema = ABI.Schema.tuple([.address, .address, .uint24, .uint256, .uint256, .uint256, .bool, .uint256, .address])

        public let exposureToken: EthAddress
        public let backingToken: EthAddress
        public let poolFee: UInt
        public let exposureAmount: Number
        public let maxSwapBackingAmount: Number
        public let maxProvidedBackingAmount: Number
        public let cappedMaxForProvidedBackingAmount: Bool
        public let feeAmount: Number
        public let feeRecipient: EthAddress

        public init(exposureToken: EthAddress, backingToken: EthAddress, poolFee: UInt, exposureAmount: Number, maxSwapBackingAmount: Number, maxProvidedBackingAmount: Number, cappedMaxForProvidedBackingAmount: Bool, feeAmount: Number, feeRecipient: EthAddress) {
          self.exposureToken = exposureToken
         self.backingToken = backingToken
         self.poolFee = poolFee
         self.exposureAmount = exposureAmount
         self.maxSwapBackingAmount = maxSwapBackingAmount
         self.maxProvidedBackingAmount = maxProvidedBackingAmount
         self.cappedMaxForProvidedBackingAmount = cappedMaxForProvidedBackingAmount
         self.feeAmount = feeAmount
         self.feeRecipient = feeRecipient
        }

        public var encoded: Hex {
            asValue.encoded
        }

        public var asValue: ABI.Value {
            .tuple9(.address(exposureToken),
             .address(backingToken),
             .uint24(poolFee),
             .uint256(exposureAmount),
             .uint256(maxSwapBackingAmount),
             .uint256(maxProvidedBackingAmount),
             .bool(cappedMaxForProvidedBackingAmount),
             .uint256(feeAmount),
             .address(feeRecipient))
        }

        public static func decode(hex: Hex) throws -> LoopInfo {
            if let value = try? schema.decode(hex) {
                return try decodeValue(value)
            }
  // both versions are valid encodings of tuples with dynamic fields ( bytes or string ), so try both decodings
  if case let .tuple1(wrappedValue) = try? ABI.Schema.tuple([schema]).decode(hex) {
      return try decodeValue(wrappedValue)
  }
  // retry original to throw the error
  return try decodeValue(schema.decode(hex))


        }

        public static func decodeValue(_ value: ABI.Value) throws -> LoopInfo {
            switch value {
            case let .tuple9(.address(exposureToken),
             .address(backingToken),
             .uint24(poolFee),
             .uint256(exposureAmount),
             .uint256(maxSwapBackingAmount),
             .uint256(maxProvidedBackingAmount),
             .bool(cappedMaxForProvidedBackingAmount),
             .uint256(feeAmount),
             .address(feeRecipient)):
                return LoopInfo(exposureToken: exposureToken, backingToken: backingToken, poolFee: poolFee, exposureAmount: exposureAmount, maxSwapBackingAmount: maxSwapBackingAmount, maxProvidedBackingAmount: maxProvidedBackingAmount, cappedMaxForProvidedBackingAmount: cappedMaxForProvidedBackingAmount, feeAmount: feeAmount, feeRecipient: feeRecipient)
            default:
                throw ABI.DecodeError.mismatchedType(value.schema, schema)
            }
        }
    }
