    public static let loopFn = ABI.Function(
            name: "loop",
            inputs: [.address, .tuple([.address, .address, .address, .address, .uint256]), .tuple([.address, .address, .uint24, .uint256, .uint256, .uint256, .bool, .uint256, .address])],
            outputs: []
    )

    public static func loop(morpho: EthAddress, morphoMarketParams: MarketParams, loopInfo: LoopInfo, withFunctions ffis: EVM.FFIMap = [:]) throws -> Result<(), RevertReason> {
            do {
                let query = try loopFn.encoded(with: [.address(morpho), morphoMarketParams.asValue, loopInfo.asValue])
                let result = try EVM.runQuery(bytecode: runtimeCode, query: query, withErrors: errors, withFunctions: ffis)
                let decoded = try loopFn.decode(output: result)

                switch decoded {
                case  .tuple0:
                    return .success(())
                default:
                    throw ABI.DecodeError.mismatchedType(decoded.schema, loopFn.outputTuple)
                }
            } catch let EVM.QueryError.error(e, v) {
                return .failure(rewrapError(e, value: v))
            }
    }


    public static func loopDecode(input: Hex) throws -> (EthAddress, MarketParams, LoopInfo) {
        let decodedInput = try loopFn.decodeInput(input: input)
        switch decodedInput {
        case let .tuple3(.address(morpho), .tuple5(.address(loanToken),
 .address(collateralToken),
 .address(oracle),
 .address(irm),
 .uint256(lltv)), .tuple9(.address(exposureToken),
 .address(backingToken),
 .uint24(poolFee),
 .uint256(exposureAmount),
 .uint256(maxSwapBackingAmount),
 .uint256(maxProvidedBackingAmount),
 .bool(cappedMaxForProvidedBackingAmount),
 .uint256(feeAmount),
 .address(feeRecipient))):
            return try (morpho, MarketParams(loanToken: loanToken, collateralToken: collateralToken, oracle: oracle, irm: irm, lltv: lltv), LoopInfo(exposureToken: exposureToken, backingToken: backingToken, poolFee: poolFee, exposureAmount: exposureAmount, maxSwapBackingAmount: maxSwapBackingAmount, maxProvidedBackingAmount: maxProvidedBackingAmount, cappedMaxForProvidedBackingAmount: cappedMaxForProvidedBackingAmount, feeAmount: feeAmount, feeRecipient: feeRecipient))
        default:
            throw ABI.DecodeError.mismatchedType(decodedInput.schema, loopFn.inputTuple)
        }
    }

